using System.IO;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace AIEngineerStudio;
public sealed class SystemPrompt { public string Name { get; set; }="Новый промпт"; public string Content { get; set; }=""; public override string ToString() => Name; }
public sealed class AppSettings { public string MediaImageModel { get; set; } = "gpt-image-2"; public string MediaVideoModel { get; set; } = ""; public string ApiKey {get;set;}=""; public string BaseUrl {get;set;}="https://apiduck.sytes.net/v1"; public string Model {get;set;}="gpt-5.6-terra"; public string Theme {get;set;}="Graphite (по умолчанию)"; public string PromptTemplate {get;set;}="Ты — автономный senior-разработчик. Отвечай на русском языке и используй Markdown."; public double Temperature {get;set;}=.2; public int MaxTokens {get;set;}=8192; public string PythonPath {get;set;}="python"; public bool ComputerControlEnabled {get;set;}=false; public bool InteractiveTaskClarification {get;set;}=true; public bool AutomaticModelSelection { get; set; } = true; public string EconomyModel { get; set; } = "gpt-5.6-luna"; public List<SystemPrompt> Prompts {get;set;}=new() { new SystemPrompt {Name="Автономный разработчик",Content="Ты — автономный senior-разработчик. Отвечай на русском языке и используй Markdown."}, new SystemPrompt {Name="WPF .NET мастер",Content="Ты — выдающийся senior WPF/.NET-разработчик и архитектор desktop-приложений. Проектируй решения production-уровня на C# и современном .NET с чистой архитектурой, MVVM, DI, async/await и SOLID. Глубоко разбирайся в WPF, XAML, binding, styles, templates, commands, ресурсах, потоках UI, производительности, доступности и Windows API. Перед изменениями изучай структуру проекта и существующие соглашения. Предлагай простые, поддерживаемые решения, учитывай обработку ошибок, отмену операций, безопасность и совместимость. Пиши точный компилируемый код, указывай конкретные файлы и места изменений, не ломай существующую функциональность. После реализации проверяй сборку и тесты, а результат объясняй кратко на русском языке в Markdown."}, new SystemPrompt {Name="Code Review",Content="Проведи профессиональный code review и предложи точные исправления в Markdown."}, new SystemPrompt {Name="Fullstack React",Content="Ты — ведущий Fullstack-разработчик и архитектор интерфейсов."} }; }
public static class SettingsStore {
 static string Dir=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"AIEngineerStudio"); static string File=>Path.Combine(Dir,"settings.json");
 public static AppSettings Load(){try{if(!System.IO.File.Exists(File))return new();var s=JsonSerializer.Deserialize<AppSettings>(System.IO.File.ReadAllText(File))??new();s.ApiKey=Unprotect(s.ApiKey);if(s.Prompts==null||s.Prompts.Count==0)s.Prompts=new AppSettings().Prompts;else {var wpf=new AppSettings().Prompts.FirstOrDefault(p=>p.Name=="WPF .NET мастер");if(wpf!=null&&!s.Prompts.Any(p=>p.Name==wpf.Name))s.Prompts.Add(wpf);}return s;}catch{return new();}}
 public static void Save(AppSettings s){Directory.CreateDirectory(Dir);var copy=JsonSerializer.Deserialize<AppSettings>(JsonSerializer.Serialize(s))!;copy.ApiKey=Protect(copy.ApiKey);System.IO.File.WriteAllText(File,JsonSerializer.Serialize(copy,new JsonSerializerOptions{WriteIndented=true}));}
 static string Protect(string value){if(string.IsNullOrEmpty(value))return "";try{return Convert.ToBase64String(ProtectedData.Protect(Encoding.UTF8.GetBytes(value),null,DataProtectionScope.CurrentUser));}catch{return value;}}
 static string Unprotect(string value){if(string.IsNullOrEmpty(value))return "";try{return Encoding.UTF8.GetString(ProtectedData.Unprotect(Convert.FromBase64String(value),null,DataProtectionScope.CurrentUser));}catch{return value;}}
}
